Circuit.Algorithm:
function LatticeCommit(prev[32], payload[64]) -> next[32]: b = payload[0:32] c = payload[32:64] t0 = CyclicConvolve(K0, prev) t1 = CyclicConvolve(K1, b) t2 = CyclicConvolve(K2, c) next[i] = t0[i] ^ t1[i] ^ t2[i] for i in 0..31
function CyclicConvolve(a[32], b[32]) -> c[32]: c[k] = XOR_{i=0..31} GF256_Mul(a[i], b[(k-i) mod 32])
function GF256_Mul(x, y) -> z: z = 0 for i in 0..7: if (y & 1): z ^= x hi = x & 0x80; x <<= 1 if hi: x ^= 0x1B y >>= 1 return z
